import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Panel","description":"","frontmatter":{},"headers":[],"relativePath":"components/panel.md","filePath":"components/panel.md"}'),r={name:"components/panel.md"};function n(i,e,h,s,c,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="panel" tabindex="-1">Panel <a class="header-anchor" href="#panel" aria-label="Permalink to &quot;Panel&quot;">​</a></h1><p>Panel is a column of the screen that holds a head, content that scrolls and a foot: a side column, a left or right panel, or a dock (a panel along the bottom whose height changes).</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the columns beside the stage. Put a <a href="./toolbar">Toolbar</a> in <code>head</code> and, when the panel has a main action, a <a href="./footer">Footer</a> in <code>foot</code>. The content has no padding: stack lists, a <a href="./tree">Tree</a> and <a href="./section-header">SectionHeader</a> groups with Stack gap 0, and put text and fields in a <a href="./block">Block</a>. Use <code>fit</code> for a floating pane over the stage that should be as tall as its content, and <code>side=&quot;fill&quot;</code> with <code>resizable</code> for a dock whose height the user changes.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>side</code></td><td><code>panel</code></td><td><code>rail</code> (the side column&#39;s width), <code>panel</code> or <code>fill</code></td></tr><tr><td><code>fit</code></td><td><code>false</code></td><td>As tall as the content, up to the container</td></tr><tr><td><code>resizable</code></td><td><code>false</code></td><td>A grip along the top edge that changes the height</td></tr><tr><td><code>onresize</code></td><td></td><td>Called with the height the grip asks for, in px</td></tr><tr><td><code>resizeLabel</code></td><td></td><td>The name of the grip; required with <code>resizable</code></td></tr><tr><td><code>label</code></td><td></td><td>The name of the panel as a region</td></tr><tr><td><code>head</code></td><td></td><td>The head, a Toolbar (a snippet)</td></tr><tr><td><code>foot</code></td><td></td><td>The foot, a Footer (a snippet)</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The order is fixed: head, content, foot. The head and the foot keep their height; only the content shrinks, and it is the only part that scrolls. <code>rail</code> is <code>--kata-width-rail</code> wide and <code>panel</code><code>--kata-width-panel</code>, never wider than the container; <code>fill</code> takes the rest of the row. The surface is the panel color. The content has no padding and declares pad-md as the inset of the items that reach its edges, so a list item or a tree row brings its own padding; text in the content always sits in a component that brings padding. Controls inside have a button&#39;s height. The grip of <code>resizable</code> has no look, only the resize cursor; it is pad-sm tall, the arrow keys move it by 32px, and the application keeps the height and its limits.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/panel/" title="Panel" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/panel/" target="_blank" rel="noopener">Panel</a></figcaption></figure>',10)])])}const m=t(r,[["render",n]]);export{f as __pageData,m as default};
